import {
  GET_MANUFACTURERS,
  GET_MANUFACTURERS_SUCCESS,
  GET_MANUFACTURERS_FAILED,
  CREATE_MANUFACTURER,
  CREATE_MANUFACTURER_FAILED,
  CREATE_MANUFACTURER_SUCCESS,
  UPDATE_MANUFACTURER,
  UPDATE_MANUFACTURER_SUCCESS,
  UPDATE_MANUFACTURER_FAILED,
  RESET_REDUX,
  SEARCH_MANUFACTURERS_FAILED,
  SEARCH_MANUFACTURERS_SUCCESS,
  SEARCH_MANUFACTURERS,
} from "./constants";

export const resetRedux = () => ({
  type: RESET_REDUX,
});

export const addManufacturer = (manufacturer) => ({
  type: CREATE_MANUFACTURER,
  payload: manufacturer,
});

export const updateManufacturer = (manufacturer, id) => ({
  type: UPDATE_MANUFACTURER,
  payload: { data: manufacturer, id: id },
});

export const getManufacturers = () => ({
  type: GET_MANUFACTURERS,
});

export const getManufacturersSuccess = (manufacturers) => ({
  type: GET_MANUFACTURERS_SUCCESS,
  payload: manufacturers,
});

export const getManufacturersFailed = (message, errors) => ({
  type: GET_MANUFACTURERS_FAILED,
  payload: { message: message, errors: errors },
});

export const createManufacturerSuccess = (manufacturers) => ({
  type: CREATE_MANUFACTURER_SUCCESS,
  payload: manufacturers,
});

export const createManufacturerFailed = (message, errors) => ({
  type: CREATE_MANUFACTURER_FAILED,
  payload: { message: message, errors: errors },
});

export const updateManufacturerSuccess = (manufacturers) => ({
  type: UPDATE_MANUFACTURER_SUCCESS,
  payload: manufacturers,
});

export const updateManufacturerFailed = (message, errors) => ({
  type: UPDATE_MANUFACTURER_FAILED,
  payload: { message: message, errors: errors },
});

//Search
export const searchManufacturers = (query) => ({
  type: SEARCH_MANUFACTURERS,
  payload: query,
});
export const searchManufacturerSuccess = (manufacturers) => ({
  type: SEARCH_MANUFACTURERS_SUCCESS,
  payload: manufacturers,
});

export const searchManufacturerFailed = (message, errors) => ({
  type: SEARCH_MANUFACTURERS_FAILED,
  payload: { message: message, errors: errors },
});
